import hashlib


class RecordProgram:
    """Recomputes the record's checkable result."""

    def __init__(self):
        self.figures = {"caption_coverage": 100, "control_modes": 3, "door_width_cm": 120, "seated_places": 8}

    def run(self):
        total = sum(self.figures.values())
        return {"total": total,
                "digest": hashlib.sha256(str(total).encode()).hexdigest()}
